function renderChat(){if(!$('chat'))return;$('chat').innerHTML=chat.map(m=>'<div class="message '+(m.role==='user'?'student':'')+'"><small>'+(m.role==='user'?'我的问题':current.live?'AI 老师':'合成示例 · 老师提示')+'</small>'+esc(m.content)+'</div>').join('');math($('chat'));$('chat').scrollTop=$('chat').scrollHeight;}
async function ask(text){if(!text||!current)return;const history=chat.slice(-16);chat.push({role:'user',content:text});$('ask-input').value='';renderChat();$('send-ask').disabled=true;let reply;try{if(current.live){reply=(await api('followup',{question:current.question,attempt:current.attempt||'',message:text,history})).reply;}else if(/提示/.test(text))reply='先只想这一步：'+current.hints[0];else if(/换|另一|方法/.test(text))reply=current.alternate;else if(/为什么|列式|原理/.test(text))reply=current.why;else if(/简单|不懂|不会|什么意思/.test(text))reply='Judy，我们先不急着算。'+current.known+' 想一想：'+current.ask+' 记住：'+current.key;else reply='这段是合成教学演示，暂不能理解所有自由追问。你可以试试“为什么这样列式”“再简单讲一遍”或“换一种方法”。我不会把预设回答当成实时 AI 分析。';chat.push({role:'assistant',content:reply});const note=store.notes.find(n=>n.sampleId===current.id);if(note){note.chat=chat;persist();}renderChat();}catch(err){chat.push({role:'assistant',content:'本次追问未成功：'+err.message});renderChat();}finally{$('send-ask').disabled=false;}}
function saveCurrent(){if(!current)return;let n=store.notes.find(n=>n.sampleId===current.id);if(n){n.lesson=structuredClone(current);n.chat=structuredClone(chat);n.attempt=current.attempt||'';n.knowledgeTags=current.knowledgeTags||n.knowledgeTags||[];n.updatedAt=new Date().toISOString();}else{n={id:crypto.randomUUID(),sampleId:current.id,question:current.question,attempt:current.attempt||'',lesson:structuredClone(current),chat:structuredClone(chat),createdAt:new Date().toISOString(),nextReview:new Date(Date.now()+864e5).toISOString(),reviews:0,state:'待复习',cause:'尚未归因',reflection:'',answer:current.steps.join('\n'),synthetic:!current.live,knowledgeTags:current.knowledgeTags||inferTopics(current).map(t=>t.name)};store.notes.unshift(n);event('save',n.id);}if(persist()){toast('已保存讲解与问答；明天回来独立重做。');$('save-current').textContent='已加入 · 更新讲解记录';renderRecent();}}
function date(s){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric'}).format(new Date(s));}
function renderRecent(){$('note-count').textContent=store.notes.length;$('recent').innerHTML=store.notes.length?store.notes.slice(0,3).map(n=>'<button class="mini-note" data-learn="'+n.id+'"><span class="sample-tag">'+(n.synthetic?'合成':'已核对')+'</span> '+esc(n.lesson?.name||n.lesson?.topic||'自编题目')+'<br>'+esc(n.question.slice(0,40))+'…<br><small>'+date(n.createdAt)+' · '+esc(n.state)+'</small></button>').join(''):'<p class="field-note">还没有记录。先体验一道合成样题，再把方法存下来。</p>';}
