function validTags(tags){return tags===undefined||(Array.isArray(tags)&&tags.length<=8&&tags.every(t=>typeof t==='string'&&t.length>0&&t.length<=40));}
function validNote(n){return n&&typeof n.id==='string'&&typeof n.question==='string'&&n.question.length<=6000&&n.synthetic===true&&typeof n.createdAt==='string'&&Number.isFinite(Date.parse(n.createdAt))&&typeof n.nextReview==='string'&&Number.isFinite(Date.parse(n.nextReview))&&Number.isInteger(n.reviews)&&n.reviews>=0&&typeof n.cause==='string'&&typeof n.reflection==='string'&&typeof n.answer==='string'&&typeof n.state==='string'&&(samples.some(s=>s.id===n.sampleId)||(n.pending===true&&typeof n.sampleId==='string'&&n.sampleId.startsWith('manual-')))&&validTags(n.knowledgeTags)&&Array.isArray(n.chat)&&n.chat.every(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string'&&m.content.length<=15000);}
async function importData(file){if(!file)return;if(file.size>2e6)return toast('备份超过 2 MB，未导入。');try{const v=JSON.parse(await file.text());if(v.schema!==1||!Array.isArray(v.notes)||v.notes.length>500||!v.notes.every(validNote))throw new Error('仅支持本版本导出的合成数据 JSON。');if(v.courses!==undefined&&(!Array.isArray(v.courses)||v.courses.length>300||!v.courses.every(c=>topicRules.some(t=>t.id===c.topicId)&&typeof c.title==='string'&&c.title.length<=120&&typeof c.edition==='string'&&c.edition.length<=40&&c.reviewedByParent===true&&validateCourseUrl(c.url))))throw new Error('课程收藏包含不支持或不安全的链接。');const existing=new Set(store.notes.map(n=>n.id));const add=v.notes.filter(n=>!existing.has(n.id));for(const n of add){n.lesson=n.pending?{id:n.sampleId,name:'待讲解题目',question:n.question,topic:(n.knowledgeTags||[]).join('、')||'待归类',pending:true}:structuredClone(samples.find(s=>s.id===n.sampleId));store.notes.push(n);}if(Array.isArray(v.events)){const keys=new Set(store.events.map(e=>e.type+'|'+e.noteId+'|'+e.at));for(const e of v.events.slice(0,3000))if(e&&typeof e.type==='string'&&['lesson','save','practice-correct','practice-attempt','review-independent','review-help'].includes(e.type)&&typeof e.noteId==='string'&&Number.isFinite(Date.parse(e.at))&&!keys.has(e.type+'|'+e.noteId+'|'+e.at)){store.events.push({type:e.type,noteId:e.noteId,at:e.at});keys.add(e.type+'|'+e.noteId+'|'+e.at);}}if(!Array.isArray(store.courses))store.courses=[];for(const c of v.courses||[])if(!store.courses.some(old=>old.url===c.url&&old.topicId===c.topicId&&old.edition===c.edition))store.courses.push({id:crypto.randomUUID(),topicId:c.topicId,title:c.title,edition:c.edition,url:c.url,reviewedByParent:true,createdAt:new Date().toISOString()});if(persist()){renderReport();renderRecent();toast('已合并 '+add.length+' 道合成错题及有效课程收藏，未覆盖现有记录。');}}catch(err){toast('导入失败：'+err.message);}}

