renderRecent();renderLesson();renderKnowledge();
fetch('/api/session').then(r=>r.json()).then(s=>{session=s;if(s.aiEnabled){$('connection-title').textContent='AI 服务已配置 · 题干须先核对';$('connection-detail').textContent='图片仅发送到家长配置的模型服务处理，原图默认不留存；讲解仍须核对。';}}).catch(()=>{});
const hash=location.hash.slice(1);const initial=titles[hash]?hash:'home';history.replaceState({judyApp:true,view:initial,depth:0,scroll:0},'','#'+initial);showView(initial);
window.addEventListener('popstate',e=>{const v=titles[e.state?.view]?e.state.view:(titles[location.hash.slice(1)]?location.hash.slice(1):'home');showView(v,e.state?.scroll||0);});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v]&&v!==activeView)showView(v);});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
// 测试与手动下载共用同一合成图片生成器，不对普通上传图片猜测题意。
window.judyTest={samplePng,selectSample,printCard,stats,getState:()=>structuredClone(store)};

function topicNavigationMarkup(){return '<details class="topic-navigation"><summary>选择初一知识点（'+topicRules.length+' 类，教材进度待核对）</summary><p class="field-note">选择标签后输入题目；完整的预设讲解示例仍为上方四道。</p>'+[...new Set(topicRules.map(t=>t.group))].map(group=>'<div class="topic-group"><strong>'+esc(group)+'</strong><div class="sample-row">'+topicRules.filter(t=>t.group===group).map(t=>'<button type="button" data-topic="'+t.id+'">'+esc(t.name)+'</button>').join('')+'</div></div>').join('')+'</details>';}
function renderTopicSuggestions(){const q=$('question').value.trim();const item=selected?.question===q?selected:{question:q};const inferred=inferTopics(item);if(!tagOverride)chosenTags=new Set(inferred.map(t=>t.name));const box=$('topic-suggestions');if(!box)return;box.innerHTML='<div class="topic-label"><strong>本题知识点</strong><span>文字规则候选，保存前请确认；可多选或新增</span></div><div class="sample-row">'+[...new Set([...inferred.map(t=>t.name),...chosenTags])].map(name=>'<button type="button" class="tag-choice '+(chosenTags.has(name)?'checked':'')+'" data-tag-name="'+esc(name)+'" aria-pressed="'+chosenTags.has(name)+'">'+(chosenTags.has(name)?'✓ ':'＋ ')+esc(name)+'</button>').join('')+'</div>'+(!inferred.length&&!chosenTags.size?'<p class="field-note">暂未发现明确关键词。请从知识点导航选择，或添加自定义标签；不会强行归类。</p>':'')+'<div class="ask-row"><input id="custom-topic" maxlength="40" placeholder="新增知识点，如：数轴动点问题" aria-label="新增知识点"><button type="button" id="add-custom-topic" class="secondary">添加标签</button></div>';
 box.querySelectorAll('[data-tag-name]').forEach(b=>b.onclick=()=>{tagOverride=true;const n=b.dataset.tagName;if(chosenTags.has(n))chosenTags.delete(n);else if(chosenTags.size<8)chosenTags.add(n);else return toast('每道题最多添加 8 个知识点。');renderTopicSuggestions();});$('add-custom-topic').onclick=()=>{const name=$('custom-topic').value.trim();if(!name)return;if(chosenTags.size>=8)return toast('每道题最多添加 8 个知识点。');tagOverride=true;chosenTags.add(name);renderTopicSuggestions();};}
function renderNoteTagEditor(n){let box=$('note-tags');if(!box){$('cause').insertAdjacentHTML('beforebegin','<section id="note-tags"></section>');box=$('note-tags');}const values=n.knowledgeTags||inferTopics(n.lesson||{question:n.question}).map(t=>t.name);box.innerHTML='<label class="field-label" for="note-tag-input">知识点标签（可修改、新增，用逗号分隔）</label><input id="note-tag-input" maxlength="350" value="'+esc(values.join('，'))+'" placeholder="如：工程问题，等式的性质"><p class="field-note">修改后会更新“我的知识点”与课程推荐；最多 8 个标签，每个 40 字。</p>';}
function readTagEditor(){return [...new Set(($('note-tag-input')?.value||'').split(/[,，、\n]/).map(v=>v.trim().slice(0,40)).filter(Boolean))].slice(0,8);}
function renderMyTopics(){const counts=new Map();for(const n of store.notes)for(const t of new Set(n.knowledgeTags||inferTopics(n.lesson||{}).map(x=>x.name)))counts.set(t,(counts.get(t)||0)+1);const el=$('my-topic-summary');if(el)el.innerHTML='<h3>从我的错题积累的知识点</h3>'+(counts.size?'<div class="sample-row">'+[...counts].map(([name,count])=>'<span class="note-tag">'+esc(name)+' · '+count+' 题</span>').join('')+'</div>':'<p class="field-note">保存题目或给错题添加标签后，这里自动汇总，不会编造已学知识点。</p>');}
function savePendingQuestion(){const d=pendingDraft||{question:$('question').value.trim(),attempt:$('attempt').value,grade:$('grade').value,edition:$('edition').value};if(!d.question)return toast('先填写完整题目。');if(!session.realDataEnabled&&!confirm('当前仅供合成样题试用。请确认这是自编的合成测试题，保存到本机，不包含 Judy 的真实学生数据。'))return;const tags=[...chosenTags],id=crypto.randomUUID();store.notes.unshift({id,sampleId:'manual-'+id,question:d.question,attempt:d.attempt||'',lesson:{id:'manual-'+id,name:'待讲解题目',question:d.question,topic:tags.join('、')||'待归类',pending:true},pending:true,chat:[],createdAt:new Date().toISOString(),nextReview:new Date(Date.now()+864e5).toISOString(),reviews:0,state:'待讲解',cause:'尚未归因',reflection:'',answer:'',synthetic:!session.realDataEnabled,knowledgeTags:tags});event('save',id);if(persist()){$('prompt-dialog').close();go('notebook');toast('已保存题目与知识点；解答尚未生成。');}}
function topicsFor(item){if(Array.isArray(item?.knowledgeTags)&&item.knowledgeTags.length)return item.knowledgeTags.map(name=>topicRules.find(t=>t.name===name)||{id:'custom',name,search:'七年级 数学 '+name,learn:[name],reason:'你为这道题确认的自定义知识点。'}).map(t=>({...t,basis:'已保存的知识点标签',confirmed:true}));return inferTopics(item);}
function resourceMarkup(item){const topics=topicsFor(item);const edition=store.settings.edition.trim();return '<span class="eyebrow">KNOWLEDGE TO LESSONS</span><h3>这道题，可以回看哪些知识？</h3><p class="field-note">'+(edition?'当前教材设置：'+esc(edition)+'（以学校实际教材为准）。':'教材版本待核对，暂不做具体课时匹配。')+' 候选知识点用于找课，不代表已找到对应视频。</p>'+(topics.length?topics.map(t=>{const query=t.search+(edition?' '+edition:'');const courses=matchingCourses(store.courses,t.id,edition);return '<article class="course-topic"><span class="note-tag">'+esc(t.name)+'</span><small>'+esc(t.basis)+'</small><p>'+esc(t.reason)+'</p><ul>'+t.learn.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><div class="search-keywords">建议检索词：<strong>'+esc(query)+'</strong></div><div class="lesson-actions"><button type="button" class="secondary" data-copy-keywords="'+esc(query)+'">复制检索词</button><a class="primary" href="'+PLATFORM_URL+'" target="_blank" rel="noopener noreferrer">打开国家教育平台 ↗</a></div>'+ (courses.length?courses.map(c=>'<a class="saved-course" href="'+esc(c.url)+'" target="_blank" rel="noopener noreferrer">▷ '+esc(c.title)+' <span>家长核对收藏 · '+esc(c.edition)+' ↗</span></a>').join(''):'<p class="field-note">暂无已核对的本教材课程直链。上面的按钮打开官方首页，需要在平台中选择或搜索课程。</p>')+'</article>';}).join(''):'<p>还没有足够依据判断知识点。请先核对题目文字，或手动选择知识点。</p>')+'<label class="field-label">补充或调整课程查找方向<select class="course-topic-select"><option value="">请选择知识点</option>'+topicRules.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></label><p class="field-note">官方课程在新标签页打开，由你或 Judy 在官方页面登录。课程登录状态与本网站独立。课程收藏和规则导航不属于国家平台开放接口；尚未接通课程搜索或视频播放接口。</p>';}
function bindCourseButtons(box,item){box.querySelectorAll('[data-copy-keywords]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copyKeywords);toast('已复制知识点检索词，可在官方平台中粘贴。');}catch{toast('未获得复制权限，请长按上方检索词复制。');}});const select=box.querySelector('.course-topic-select');if(select)select.onchange=()=>{const t=topicRules.find(x=>x.id===select.value);if(!t)return;const revised={...item,knowledgeTags:[t.name]};box.innerHTML=resourceMarkup(revised);bindCourseButtons(box,revised);};}
function openCourses(key){const item=key.startsWith('sample:')?samples.find(s=>s.id===key.slice(7)):(()=>{const n=store.notes.find(n=>n.id===key);return n?{...(n.lesson||{}),question:n.question,knowledgeTags:n.knowledgeTags}:null;})();if(!item)return;let d=$('courses-dialog');if(!d){document.body.insertAdjacentHTML('beforeend','<dialog id="courses-dialog"><div class="dialog-top"><span class="eyebrow">按知识点找官方课程</span><button class="close" aria-label="返回题目">×</button></div><div id="courses-dialog-body"></div><button class="secondary close">← 返回题目</button></dialog>');d=$('courses-dialog');}const body=$('courses-dialog-body');body.innerHTML=resourceMarkup(item);bindCourseButtons(body,item);d.showModal();}
function parentResourcesMarkup(){const courses=Array.isArray(store.courses)?store.courses:[];return '<div class="parent-grid resource-management"><section class="card"><h3>当前分析和报告的数据来自哪里？</h3><dl class="data-sources"><dt>题目与讲解</dt><dd>4 道本项目原创合成题、预设讲解、SVG 和追问提示。</dd><dt>知识点归类</dt><dd>'+topicRules.length+' 类原创关键词规则，以及你手动确认、新增的标签；未接入外部题库或国家平台数据库。</dd><dt>学习与复习报告</dt><dd>此浏览器实际发生的保存、练习、错因和复习操作；不代表 Judy 的真实成绩或掌握程度。</dd><dt>AI 模型</dt><dd>'+(session.aiEnabled?'服务端已配置，需逐题核对结果。':'真实 AI 图片识别、自由讲题和追问尚未接通。')+'</dd><dt>课程资源</dt><dd>官方首页入口与家长本机收藏的课程直链；未接通官方检索、播放或学习记录接口。</dd></dl></section><section class="card"><h3>维护官方课程对应表（本机）</h3><p>打开官方平台核对课名、教材版本和内容后，可将课程页链接收藏到某个知识点。之后同类错题可直接打开。收藏状态表示家长已核对，系统尚未联网复核。</p><form id="course-form"><label class="field-label" for="course-topic">知识点</label><select id="course-topic">'+topicRules.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select><label class="field-label" for="course-title">官方页面课名</label><input id="course-title" required maxlength="120" placeholder="按官方页面填写课名"><label class="field-label" for="course-edition">教材版本（与学习设置一致）</label><input id="course-edition" required maxlength="40" value="'+esc(store.settings.edition)+'" placeholder="请核对出版社、版次或年份"><label class="field-label" for="course-url">官方课程页链接</label><input id="course-url" type="url" required maxlength="2000" placeholder="https://basic.smartedu.cn/…"><label class="check-label"><input type="checkbox" id="course-reviewed" required> 我已核对课名、教材版本和课程内容，链接可以打开。</label><button class="primary" type="submit">保存课程收藏</button><p id="course-error" class="field-note" role="status"></p></form><div id="saved-courses">'+(courses.length?courses.map(c=>'<article class="saved-course"><strong>'+esc(c.title)+'</strong><span>'+esc(c.edition)+' · '+esc(topicRules.find(t=>t.id===c.topicId)?.name||'未归类')+'</span><a href="'+esc(validateCourseUrl(c.url)?c.url:PLATFORM_URL)+'" target="_blank" rel="noopener noreferrer">在官方平台打开 ↗</a></article>').join(''):'<p class="field-note">尚未收藏具体课程。请勿填写账号密码、验证码、登录回调或带授权令牌的地址。</p>')+'</div></section></div>';}
function bindParentResources(){$('course-form').onsubmit=e=>{e.preventDefault();const url=$('course-url').value.trim(),edition=$('course-edition').value.trim(),title=$('course-title').value.trim();if(!title||!edition||!$('course-reviewed').checked)return;if(!validateCourseUrl(url)){$('course-error').textContent='请填写国家中小学智慧教育平台的具体 HTTPS 课程页，不能用首页、登录页、带密码或令牌的地址。';return;}if(!Array.isArray(store.courses))store.courses=[];const entry={id:crypto.randomUUID(),topicId:$('course-topic').value,title,edition,url,reviewedByParent:true,createdAt:new Date().toISOString()};if(store.courses.some(c=>c.url===url&&c.topicId===entry.topicId&&c.edition===edition))return toast('这条课程已收藏。');store.courses.push(entry);if(persist()){renderReport();toast('已保存课程收藏，同知识点和教材版本下可直接打开。');}};}
